{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine, a phenolic opioid analgesic structurally similar to the query, has a mean absolute oral bioavailability of about 18% in healthy subjects, below the 20% threshold, indicating substantial first-pass metabolism of phenolic opioids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Meptazinol, another phenolic opioid with a tertiary amine, shows an absolute oral bioavailability of only 8.7 ± 1.6% in healthy young volunteers, well below 20%, supporting a low-F outcome for the query due to similar phenol/amine first-pass liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pethidine, an opioid without a phenolic group, has a higher oral bioavailability of about 50%, suggesting that the phenolic moiety is a key driver of low bioavailability; this is contradictory to low but less transferable because pethidine lacks the phenol and morphinan-like scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest phenolic opioid analogues, pentazocine and meptazinol, have absolute oral bioavailability below 20% in healthy subjects due to extensive first-pass metabolism. The query shares the phenolic opioid scaffold and metabolic liabilities. Higher-F analogues either lack the phenolic group or are less structurally relevant, so low bioavailability is better supported.",
  "evidence_gaps": [
    "No direct human oral bioavailability data exist for the query molecule.",
    "Healthy-subject bioavailability data for ciramadol, a phenolic opioid with high F in cirrhosis, are unavailable.",
    "The extent of first-pass glucuronidation/sulfation of the query's phenol is not directly measured.",
    "Potential transporter effects or active metabolite contributions are not captured by the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

